local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ItemsFolder = ReplicatedStorage:WaitForChild("LocalReplicated")

local args = {
    "StorylineAdvanced",
    "Sharpe", -- Edit this to Doug or any NPC questline you haven't done
    {
        {
            name = "Money",
            amount = 503333333
        },
        {
            name = "WonderToken",
            amount = 10000003
        },
        {
            name = "Essence",
            amount = 1333333
        },
        {
            name = "ResourceCapsule",
            amount = 1333333
        },
        {
            name = "SpeedCapsule",
            amount = 1333333
        },
        {
            name = "Orbz",
            amount = 1333333
        },
        {
            name = "ReleaseCoin",
            amount = 1333333
        }
    }
}

local itemsList = args[3]

-- Prevent duplicates
local added = {}

for _, item in ipairs(ItemsFolder:GetDescendants()) do
    -- Skip folders and non-purchasable junk
    if item:IsA("Folder") then
        continue
    end

    if not added[item.Name] then
        added[item.Name] = true

        table.insert(itemsList, {
            name = item.Name,
            amount = 10000
        })
    end
end

local changeDataRemote = ReplicatedStorage
    :WaitForChild("ClientToServer")
    :WaitForChild("DataEvents")
    :WaitForChild("ChangeData")

changeDataRemote:FireServer(unpack(args))

